import{_ as t,o as _,c as e,a3 as o}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/54-“幽灵般”的前任和“理想型”的魔力.md","filePath":"books/attached/54-“幽灵般”的前任和“理想型”的魔力.md","lastUpdated":1794298621000}'),p={name:"books/attached/54-“幽灵般”的前任和“理想型”的魔力.md"};function r(s,a,d,n,c,i){return _(),e("div",null,[...a[0]||(a[0]=[o('<h3 id="幽灵般-的前任和-理想型-的魔力" tabindex="-1">“幽灵般”的前任和“理想型”的魔力 <a class="header-anchor" href="#幽灵般-的前任和-理想型-的魔力" aria-label="Permalink to &quot;“幽灵般”的前任和“理想型”的魔力&quot;">​</a></h3><p>回避型依恋风格的人，在爱情中会采取两种最阴险的自我欺骗手段。会承认自己对前任有所眷恋，还会觉得自己的理想型就近在咫尺，却不是现任伴侣，因此很可能成为现在感情的逃兵。对于“完美伴侣”的憧憬，很可能变成回避型人群在爱情中不够专一的罪魁祸首。这种憧憬会让人觉得现任伴侣成了美好生活中的那点瑕疵，总感觉对方有哪里不太好。这种做法不仅会使得双方之间的距离渐渐疏远，也会令对方陷入无比困惑中。当伴侣知道你是那么怀恋前任，或是那样期待一个完美伴侣时，对方或许会觉得你十分需要亲密感。而殊不知，这都只是你逃避亲密关系的伎俩而已。</p><p>||“幽灵般”的前任</p><p>回避型人群不断地抱怨当下的恋情，也非常容易时常想起曾经失去的爱情。他们几乎忘记了前任是如何令人怒不可遏，也忘记与之在一起时发生的一切不快，还会静静思考曾经的感情到底出了什么问题。总之这种对逝去爱情的强烈怀念，这就叫作“幽灵前任现象”。</p><p>一般来说，正如卡罗尔一跟鲍勃分手就立马“重新”想起了对方的美好一样，回避型人群一旦与先前索然无味的伴侣拉开了时空上的距离，便会有奇妙的事情发生：那充满爱慕和欣赏的感觉回来了！一旦与伴侣回到安全距离以外，那种因为太过亲密而产生的威胁就回来了，回避型人群便不再感到自己的真实感觉受到压抑。由此会回想起前任的一切美好品质，甚至会说服自己，那个人就是前所未有的完美伴侣。当然，回避型人群并不能清楚地明了，当时两人为什么会闹掰，也不会记得一开始是为什么离开对方，或是怎样逼得对方无路可走，最终选择分开。事实上，回避型人群只是将前任伴侣推上了神坛，作为“永远逝去的一生挚爱”供奉起来。有时候回避型人群的确想和前任重修旧好，于是开始了不断接近而后逃离的恶性循环。有时候，即使对方同样处于单身状态，回避型人群也不愿意回到对方身边，与此同时又继续时不时地在心底思念着前任。</p><p>这种对于前任的留恋，显然会影响新恋情的发生。因为这其实是一种去激活策略，阻碍了回避型人群接近其他人。纵使他们永远不会和心心念念的前任重修旧好，但是这种心不在焉的认知，就足以让新的伴侣在比较之下，感觉到自己的无足轻重。</p><p>||“理想型”的魔力</p><p>不知你有没有过这样的经历，跟一个心中无限爱慕的对象一块出去，但随着接近和了解，你感觉他完全不是你想象中那么迷人，从而陷入无限的失望。同理，当你怀着郑重的心情，和一个曾经奉为理想型、十分在意的人开始一段恋情，长此以往，你却会渐渐感觉到事实令你万分失望。你会渐渐觉得对方吃相怪异，擤鼻涕的样子令你难以忍受。他一开始在你心中的光辉形象渐渐消散，你吃不消那种令人窒息的亲密关系，开始打退堂鼓了。事实上，这种来势汹汹的消极情绪，也是你的一种去激活策略，这种策略在你不经意间触发，而后令你的依恋需要被抑制。</p><p>这时候你并不会想要深入探讨这个问题，你会觉得自己只是爱得不够彻底，想把对方推开，还觉得这就是恋爱中的人之常情。你的恋人会非常挫败和不安，而这一切会令你更加觉得他不是那个“对的人”。你也会游走在一段又一段恋情之中，陷入另一场恶性循环。你坚信，一旦自己找到那个真正的“理想型”，就可以不费吹灰之力地让你们的关系上升到另一种更高的境界。</p>',9)])])}const m=t(p,[["render",r]]);export{h as __pageData,m as default};
